import { expect, test, uniqueName } from "../../fixtures";

const examples: Array<{ field: "name" | "category" | "contact_email"; value: string }> = [
  { field: "name", value: "A" },
  { field: "category", value: "furniture" },
  { field: "contact_email", value: "not-an-email" },
];

test.describe("Manage vendors: reject invalid vendor fields", () => {
  for (const { field, value } of examples) {
    test(`rejects ${field} set to "${value}" with validation_error naming the field`, { tag: "@VEN-02" }, async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const body: Record<string, string> = {
        name: uniqueName("Invalid Field Vendor"),
        category: "logistics",
        contact_email: "ops@acme.example",
      };
      body[field] = value;

      // Act
      const response = await member.post("/api/vendors", { data: body });
      const text = await response.text();

      // Assert
      expect(response.status(), text).toBe(422);
      const json = JSON.parse(text);
      expect(json.error?.code, text).toBe("validation_error");
      const fieldNames = (json.error?.fields ?? []).map((f: { field: string }) => f.field);
      expect(fieldNames, text).toContain(field);
      expect(fieldNames, text).toEqual([field]);
    });
  }
});
